export const prepareScripts=t=>{let e=[];return t.querySelectorAll("script").forEach(t=>{let r=document.createElement("script");Array.from(t.attributes).forEach(t=>r.setAttribute(t.name,t.value)),r.textContent=t.textContent,e.push(r),t.remove()}),e};